from pathlib import Path
import importlib,os,subprocess,sys
ROOT=Path.cwd().resolve();PKG=ROOT/"qseries_v2"/"oracle_production_learning"
MOD=PKG/"opl_002_canonical_evidence_index.py";TEST=ROOT/"test_opl_002_canonical_evidence_index.py";INIT=PKG/"__init__.py"
MODULE_SOURCE='from __future__ import annotations\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom hashlib import sha256\nimport json,re\n\nfrom .opl_001_production_learning_foundation import connect\n\nOPL_002_BUILD_ID="OPL-002"\nOPL_002_REVISION="OPL_002_CANONICAL_EVIDENCE_INDEX_V1"\nINDEX_TABLE="oracle_production_learning_evidence_index"\nCURSOR_TABLE="oracle_production_learning_evidence_cursor"\n\n@dataclass(frozen=True)\nclass IndexedEvidence:\n    ticker:str\n    observation_id:str\n    evidence_hash:str\n    sequence_number:int\n    observed_at:str\n    observation_type:str\n\ndef ensure_evidence_index_schema(root=None):\n    ddl=f"""\n    CREATE TABLE IF NOT EXISTS public.{INDEX_TABLE}(\n      observation_id TEXT PRIMARY KEY,\n      ticker TEXT NOT NULL,\n      evidence_hash TEXT NOT NULL,\n      sequence_number BIGINT NOT NULL,\n      observed_at TEXT NOT NULL,\n      observation_type TEXT NOT NULL,\n      indexed_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()\n    );\n    CREATE INDEX IF NOT EXISTS oracle_production_learning_evidence_ticker_idx\n      ON public.{INDEX_TABLE}(ticker,sequence_number DESC);\n\n    CREATE TABLE IF NOT EXISTS public.{CURSOR_TABLE}(\n      cursor_id INTEGER PRIMARY KEY CHECK(cursor_id=1),\n      indexed_through_sequence BIGINT NOT NULL DEFAULT 0,\n      updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()\n    );\n    INSERT INTO public.{CURSOR_TABLE}(cursor_id,indexed_through_sequence)\n    VALUES(1,0) ON CONFLICT(cursor_id) DO NOTHING;\n    """\n    with connect(root,autocommit=True) as conn:\n        with conn.cursor() as cur:cur.execute(ddl)\n    return True\n\ndef _decode(value):\n    if isinstance(value,dict):return value\n    if isinstance(value,(bytes,bytearray,memoryview)):\n        value=bytes(value).decode("utf-8","ignore")\n    if isinstance(value,str):\n        try:\n            v=json.loads(value)\n            return v if isinstance(v,dict) else {}\n        except Exception:return {}\n    return {}\n\ndef _ticker_from_value(value):\n    s=str(value or "").strip().upper()\n    if s and re.fullmatch(r"KX[A-Z0-9_.:-]+",s):return s\n    return ""\n\ndef recover_ticker(payload,source_observation_id=""):\n    p=_decode(payload)\n    keys=("ticker","market_ticker","marketTicker","symbol")\n    stack=[p]\n    seen=0\n    while stack and seen<100:\n        cur=stack.pop();seen+=1\n        if isinstance(cur,dict):\n            for k in keys:\n                t=_ticker_from_value(cur.get(k))\n                if t:return t\n            for v in cur.values():\n                if isinstance(v,(dict,list,tuple)):stack.append(v)\n        elif isinstance(cur,(list,tuple)):\n            stack.extend(x for x in cur if isinstance(x,(dict,list,tuple)))\n    return _ticker_from_value(source_observation_id)\n\ndef _hash(row):\n    h=str(row.get("content_hash") or row.get("observation_id") or "")\n    if len(h)==64 and all(c in "0123456789abcdefABCDEF" for c in h):return h.lower()\n    return sha256(json.dumps(row,sort_keys=True,separators=(",",":"),default=str).encode()).hexdigest()\n\ndef sync_evidence_index(root=None,batch_size=5000,max_batches=20,backfill_if_empty=100000):\n    root=Path(root or Path.cwd()).resolve();ensure_evidence_index_schema(root)\n    inserted=0;scanned=0\n    with connect(root) as conn:\n        with conn.cursor() as cur:\n            cur.execute(f"SELECT indexed_through_sequence FROM public.{CURSOR_TABLE} WHERE cursor_id=1")\n            cursor=int(cur.fetchone()[0])\n            if cursor==0:\n                cur.execute("SELECT COALESCE(MAX(sequence_number),0) FROM public.oracle_canonical_observations")\n                maxseq=int(cur.fetchone()[0])\n                cursor=max(0,maxseq-int(backfill_if_empty))\n            for _ in range(int(max_batches)):\n                cur.execute("""SELECT sequence_number,observation_id,content_hash,source_observation_id,\n                               observation_type,observed_at,canonical_observation_json\n                               FROM public.oracle_canonical_observations\n                               WHERE sequence_number>%s\n                               ORDER BY sequence_number ASC LIMIT %s""",(cursor,int(batch_size)))\n                rows=cur.fetchall()\n                if not rows:break\n                for r in rows:\n                    scanned+=1\n                    row={"sequence_number":r[0],"observation_id":r[1],"content_hash":r[2],\n                         "source_observation_id":r[3],"observation_type":r[4],\n                         "observed_at":r[5],"canonical_observation_json":r[6]}\n                    ticker=recover_ticker(r[6],r[3])\n                    cursor=max(cursor,int(r[0]))\n                    if not ticker:continue\n                    cur.execute(f"""INSERT INTO public.{INDEX_TABLE}\n                        (observation_id,ticker,evidence_hash,sequence_number,observed_at,observation_type)\n                        VALUES(%s,%s,%s,%s,%s,%s) ON CONFLICT(observation_id) DO NOTHING""",\n                        (str(r[1]),ticker,_hash(row),int(r[0]),str(r[5]),str(r[4])))\n                    inserted+=cur.rowcount\n                cur.execute(f"""UPDATE public.{CURSOR_TABLE}\n                    SET indexed_through_sequence=%s,updated_at=clock_timestamp() WHERE cursor_id=1""",(cursor,))\n                conn.commit()\n                if len(rows)<int(batch_size):break\n    return {"scanned":scanned,"inserted":inserted,"indexed_through_sequence":cursor}\n\ndef find_pre_settlement_evidence(root,ticker,settlement_ts,limit=5):\n    result=find_pre_settlement_evidence_batch(root,{str(ticker).upper():str(settlement_ts)},limit)\n    return result.get(str(ticker).upper(),())\n\ndef find_pre_settlement_evidence_batch(root,ticker_to_settlement,limit=5):\n    ensure_evidence_index_schema(root)\n    wanted={str(k).upper():str(v) for k,v in dict(ticker_to_settlement).items() if str(k).strip()}\n    if not wanted:return {}\n    tickers=tuple(wanted)\n    with connect(root) as conn:\n        with conn.cursor() as cur:\n            cur.execute(f"""SELECT ticker,observation_id,evidence_hash,sequence_number,observed_at,observation_type\n              FROM public.{INDEX_TABLE}\n              WHERE ticker = ANY(%s)\n              ORDER BY ticker,sequence_number DESC""",(list(tickers),))\n            rows=cur.fetchall()\n    out={t:[] for t in tickers}\n    for r in rows:\n        ticker=str(r[0]).upper()\n        if ticker not in wanted or len(out[ticker])>=int(limit):continue\n        if str(r[4]) >= wanted[ticker]:continue\n        out[ticker].append(IndexedEvidence(str(r[0]),str(r[1]),str(r[2]),int(r[3]),str(r[4]),str(r[5])))\n    return {k:tuple(v) for k,v in out.items()}\n\ndef verify_opl_002_canonical_evidence_index(root=None):\n    return OPL_002_BUILD_ID=="OPL-002" and recover_ticker({"ticker":"KXBTC15M-26AUG181830-30"})=="KXBTC15M-26AUG181830-30"\n';TEST_SOURCE='import unittest\nfrom qseries_v2.oracle_production_learning.opl_002_canonical_evidence_index import *\nclass T(unittest.TestCase):\n    def test_direct(self):self.assertEqual(recover_ticker({"ticker":"KXTEST-1"}),"KXTEST-1")\n    def test_nested(self):self.assertEqual(recover_ticker({"payload":{"market":{"ticker":"KXABC"}}}),"KXABC")\n    def test_bad(self):self.assertEqual(recover_ticker({"ticker":"not-a-kalshi-ticker"}),"")\nif __name__=="__main__":\n    print("="*88);print(" OPL-002 CERTIFICATION TEST");print(" CANONICAL EVIDENCE INDEX");print("="*88)\n    r=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(T))\n    if not r.wasSuccessful():raise SystemExit(1)\n    print("[PASS] Canonical JSON ticker recovery certified")\n    print("[PASS] execution_authority=FALSE")\n    print("[DONE] OPL-002 CERTIFIED")\n'

def write_exact(path,text):
    path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_suffix(path.suffix+".tmp")
    tmp.write_text(text,encoding="utf-8",newline="\n")
    os.replace(tmp,path)

def restore(path,data):
    if data is None:
        if path.exists(): path.unlink()
    else:
        path.write_bytes(data)

def update_init(path,export):
    current=path.read_text(encoding="utf-8") if path.exists() else ""
    if export not in current.splitlines():
        write_exact(path,current.rstrip()+"\n"+export+"\n")

def main():
    print("="*88);print(" OPL-002 INSTALLER");print(" CANONICAL EVIDENCE INDEX");print("="*88);print("[ROOT]",ROOT)
    sys.path.insert(0,str(ROOT));up=importlib.import_module("qseries_v2.oracle_production_learning.opl_001_production_learning_foundation")
    if not up.verify_opl_001_production_learning_foundation(ROOT):raise RuntimeError("OPL-001 verification failed")
    affected=(MOD,TEST,INIT);old={p:(p.read_bytes() if p.exists() else None) for p in affected}
    try:
        write_exact(MOD,MODULE_SOURCE);write_exact(TEST,TEST_SOURCE);update_init(INIT,"from .opl_002_canonical_evidence_index import *")
        subprocess.run([sys.executable,str(TEST)],cwd=str(ROOT),check=True)
        importlib.invalidate_caches();m=importlib.import_module("qseries_v2.oracle_production_learning.opl_002_canonical_evidence_index")
        m.ensure_evidence_index_schema(ROOT);r=m.sync_evidence_index(ROOT,batch_size=5000,max_batches=20,backfill_if_empty=100000)
        print("[INDEX] scanned={scanned} inserted={inserted} through_sequence={indexed_through_sequence}".format(**r))
    except Exception:
        for p,b in old.items():restore(p,b)
        print("[ROLLBACK] OPL-002 failed; files restored");raise
    print("[PASS] Canonical observation table remains read-only")
    print("[PASS] execution_authority=FALSE")
    print("[DONE] OPL-002 INSTALLATION COMPLETE")
if __name__=="__main__":main()
